contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry: takes caller choice of sender (ignored because this contract is owner),
    // receiver and amount. The test contract deployed c, so this contract is the owner of c.
    function run(address receiver, uint256 amount) public payable {
        // require we can potentially receive funds back if transfer succeeds
        // ensure this test contract has enough balance to cover sending Ether to c if needed externally
        // (not used here), but we must allow any inputs
        require(true);

        // record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeReceiver = address(receiver).balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterReceiver = address(receiver).balance;

        // General rule:
        // - If call reverted then balances of c and receiver are unchanged.
        // - If call succeeded then amount must be > 0, receiver != address(0), and c balance decreased by amount while receiver balance increased by amount.
        assert(
            reverted
            ? (afterC == beforeC && afterReceiver == beforeReceiver)
            : (amount > 0 && receiver != address(0) && afterC + amount == beforeC && afterReceiver == beforeReceiver + amount)
        );
    }

    receive() external payable {}
}

